from typing import Annotated, Any, Literal, Union
from pydantic import BaseModel
from fastapi.dependencies.utils import analyze_param
import inspect

class Pie(BaseModel):
    time_to_cook: int
    num_ingredients: int

class ApplePie(Pie):
    fruit: Literal["apple"] = "apple"

class PumpkinPie(Pie):
    filling: Literal["pumpkin"] = "pumpkin"

def get_discriminator_value(v: Any) -> str:
    if isinstance(v, dict):
        return v.get("fruit", v.get("filling"))
    return getattr(v, "fruit", getattr(v, "filling", None))

# Mocking Discriminator and Tag as they are likely from pydantic or fastapi
class Tag:
    def __init__(self, value): self.value = value
class Discriminator:
    def __init__(self, value): self.value = value

Dessert = Annotated[
    Annotated[ApplePie, Tag("apple")] | Annotated[PumpkinPie, Tag("pumpkin")],
    Discriminator(get_discriminator_value),
]

def test_analyze_param():
    param_name = "dessert"
    annotation = Dessert
    value = inspect.Signature.empty
    is_path_param = False

    result = analyze_param(
        param_name=param_name,
        annotation=annotation,
        value=value,
        is_path_param=is_path_param,
    )

    print(f"Field info: {result.field}")
    if result.field:
        print(f"Field in_: {getattr(result.field, 'in_', 'N/A')}")

    from fastapi import params
    assert isinstance(result.field, params.Body), f"Expected Body, got {type(result.field)}"

if __name__ == "__main__":
    try:
        test_analyze_param()
        print("Test passed!")
    except Exception as e:
        print(f"Test failed: {e}")
        import traceback
        traceback.print_exc()
